bound the address copy in NFT_CT_SRC / NFT_CT_DST by priv->len
instead of by nf_ct_l3num(ct): nf_ct_get_tuple() zeroes the tuple
before pkt_to_tuple() fills in only the protocol-relevant leading
bytes, so the trailing bytes of tuple->{src,dst}.u3.all are
well-defined zero. priv->len is validated at rule load, so the
copy size is now bounded by the destination register rather than
by an untrusted field on the conntrack.

[1]: https://syzkaller.appspot.com/bug?id=389cf09cb72926114fce90dc85a2c3231dcb647c

Fixes: 45d9bcda21f4 ("netfilter: nf_tables: validate len in nft_validate_data_load()")
Suggested-by: Florian Westphal <fw@strlen.de>
Signed-off-by: Jiayuan Chen <jiayuan.chen@linux.dev>
Signed-off-by: Florian Westphal <fw@strlen.de>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

Here is the root cause:
The nft_ct_get_eval function (and nft_ct_get_fast_eval) fails to check if the conntrack is a template (nf_ct_is_template). When a template conntrack is encountered (e.g., from ct zone set), it has nf_ct_l3num == 0, causing the memcpy for NFT_CT_SRC/DST to copy 16 bytes (since l3num != NFPROTO_IPV4) even for IPv4, potentially overflowing the destination register. Additionally, the memcpy size is determined by an untrusted field (nf_ct_l3num) rather than the validated register length (priv->len). This leads to stack buffer overflow and memory corruption.

Here is the patch:

 static void nft_ct_get_eval(const struct nft_expr *expr,
 			    struct nft_regs *regs,
 			    const struct nft_pktinfo *pkt)
 {
 	const struct nft_ct *priv = nft_expr_priv(expr);
 	u32 *dest = &regs->data[priv->dreg];
 	enum ip_conntrack_info ctinfo;
 	const struct nf_conn *ct;
 	const struct nf_conn_help *help;
 	const struct nf_conntrack_tuple *tuple;
 	const struct nf_conntrack_helper *helper;
 	unsigned int state;

 	ct = nf_ct_get(pkt->skb, &ctinfo);

 	switch (priv->key) {
 	case NFT_CT_STATE:
 		if (ct)
 			state = NF_CT_STATE_BIT(ctinfo);
 		else if (ctinfo == IP_CT_UNTRACKED)
 			state = NF_CT_STATE_UNTRACKED_BIT;
 		else
 			state = NF_CT_STATE_INVALID_BIT;
 		*dest = state;
 		return;
 	default:
 		break;
 	}

-	if (ct == NULL)
+	if (!ct || nf_ct_is_template(ct))
 		goto err;

 	switch (priv->key) {
 	case NFT_CT_DIRECTION:
 		nft_reg_store8(dest, CTINFO2DIR(ctinfo));
 		return;
 	case NFT_CT_STATUS:
 		*dest = ct->status;
 		return;
 #ifdef CONFIG_NF_CONNTRACK_MARK
 	case NFT_CT_MARK:
 		*dest = READ_ONCE(ct->mark);
 		return;
 #endif
 #ifdef CONFIG_NF_CONNTRACK_SECMARK
 	case NFT_CT_SECMARK:
 		*dest = ct->secmark;
 		return;
 #endif
 	case NFT_CT_EXPIRATION:
 		*dest = jiffies_to_msecs(nf_ct_expires(ct));
 		return;
 	case NFT_CT_HELPER:
 		if (ct->master == NULL)
 			goto err;
 		help = nfct_help(ct->master);
 		if (help == NULL)
 			goto err;
 		helper = rcu_dereference(help->helper);
 		if (helper == NULL)
 			goto err;
 		strscpy_pad((char *)dest, helper->name, NF_CT_HELPER_NAME_LEN);
 		return;
 #ifdef CONFIG_NF_CONNTRACK_LABELS
 	case NFT_CT_LABELS: {
 		struct nf_conn_labels *labels = nf_ct_labels_find(ct);

 		if (labels)
 			memcpy(dest, labels->bits, NF_CT_LABELS_MAX_SIZE);
 		else
 			memset(dest, 0, NF_CT_LABELS_MAX_SIZE);
 		return;
 	}
 #endif
 	case NFT_CT_BYTES:
 	case NFT_CT_PKTS: {
 		const struct nf_conn_acct *acct = nf_conn_acct_find(ct);
 		u64 count = 0;

 		if (acct)
 			count = nft_ct_get_eval_counter(acct->counter,
 							priv->key, priv->dir);
 		memcpy(dest, &count, sizeof(count));
 		return;
 	}
 	case NFT_CT_AVGPKT: {
 		const struct nf_conn_acct *acct = nf_conn_acct_find(ct);
 		u64 avgcnt = 0, bcnt = 0, pcnt = 0;

 		if (acct) {
 			pcnt = nft_ct_get_eval_counter(acct->counter,
 						       NFT_CT_PKTS, priv->dir);
 			bcnt = nft_ct_get_eval_counter(acct->counter,
 						       NFT_CT_BYTES, priv->dir);
 			if (pcnt != 0)
 				avgcnt = div64_u64(bcnt, pcnt);
 		}

 		memcpy(dest, &avgcnt, sizeof(avgcnt));
 		return;
 	}
 	case NFT_CT_L3PROTOCOL:
 		nft_reg_store8(dest, nf_ct_l3num(ct));
 		return;
 	case NFT_CT_PROTOCOL:
 		nft_reg_store8(dest, nf_ct_protonum(ct));
 		return;
 #ifdef CONFIG_NF_CONNTRACK_ZONES
 	case NFT_CT_ZONE: {
 		const struct nf_conntrack_zone *zone = nf_ct_zone(ct);
 		u16 zoneid;

 		if (priv->dir < IP_CT_DIR_MAX)
 			zoneid = nf_ct_zone_id(zone, priv->dir);
 		else
 			zoneid = zone->id;

 		nft_reg_store16(dest, zoneid);
 		return;
 	}
 #endif
 	case NFT_CT_ID:
 		*dest = nf_ct_get_id(ct);
 		return;
 	default:
 		break;
 	}

 	tuple = &ct->tuplehash[priv->dir].tuple;
 	switch (priv->key) {
 	case NFT_CT_SRC:
-		memcpy(dest, tuple->src.u3.all,
-		       nf_ct_l3num(ct) == NFPROTO_IPV4 ? 4 : 16);
+		memcpy(dest, tuple->src.u3.all, priv->len);
 		return;
 	case NFT_CT_DST:
-		memcpy(dest, tuple->dst.u3.all,
-		       nf_ct_l3num(ct) == NFPROTO_IPV4 ? 4 : 16);
+		memcpy(dest, tuple->dst.u3.all, priv->len);
 		return;
 	case NFT_CT_PROTO_SRC:
 		nft_reg_store16(dest, (__force u16)tuple->src.u.all);
 		return;
 	case NFT_CT_PROTO_DST:
 		nft_reg_store16(dest, (__force u16)tuple->dst.u.all);
 		return;
 	case NFT_CT_SRC_IP:
 		if (nf_ct_l3num(ct) != NFPROTO_IPV4)
 			goto err;
 		*dest = (__force __u32)tuple->src.u3.ip;
 		return;
 	case NFT_CT_DST_IP:
 		if (nf_ct_l3num(ct) != NFPROTO_IPV4)
 			goto err;
 		*dest = (__force __u32)tuple->dst.u3.ip;
 		return;
 	case NFT_CT_SRC_IP6:
 		if (nf_ct_l3num(ct) != NFPROTO_IPV6)
 			goto err;
 		memcpy(dest, tuple->src.u3.ip6, sizeof(struct in6_addr));
 		return;
 	case NFT_CT_DST_IP6:
 		if (nf_ct_l3num(ct) != NFPROTO_IPV6)
 			goto err;
 		memcpy(dest, tuple->dst.u3.ip6, sizeof(struct in6_addr));
 		return;
 	default:
 		break;
 	}
 	return;
 err:
 	regs->verdict.code = NFT_BREAK;
 }



